Author: <a href data-email-masked rel="nofollow">stigl...@hotmail.com</a><br>Date: Tue Feb 19 06:36:13 2008<br>New Revision: 125<p>Added:<br>   trunk/tsDyn/R/TVAR_LRtest.R<br>   trunk/tsDyn/man/TVAR_LRtest.Rd<br>   trunk/tsDyn/man/TVECM_SeoTest.Rd   (contents, props changed)<br>Modified:<br>   trunk/tsDyn/NAMESPACE<br>   trunk/tsDyn/R/SeoTest_grid.R<br>   trunk/tsDyn/R/TAR_simul.R<br>   trunk/tsDyn/R/TVARestim.R<br>   trunk/tsDyn/R/misc.R<br>   trunk/tsDyn/R/setarTest.R<br>   trunk/tsDyn/man/TAR_simul.Rd<br>   trunk/tsDyn/man/TVAR_simul.Rd<p>Log:<br>Function TVAR_LRtest and help file for TVEC_SeoTest<p>Modified: trunk/tsDyn/NAMESPACE<br>==============================================================================<br>--- trunk/tsDyn/NAMESPACE	(original)<br>+++ trunk/tsDyn/NAMESPACE	Tue Feb 19 06:36:13 2008<br>@@ -10,7 +10,7 @@<br>        llar, llar.predict, llar.fitted, sigmoid, dsigmoid, d2sigmoid,<br>        setar, lstar, star, ncstar, availableModels, nlarDialog,<br>        linear, isLinear, nnetTs, aar, star,<br>-	OlsTVAR, TVECM, setarTest, TVAR_LRtest, TAR_simul, TVAR_simul)<br>+	OlsTVAR, TVECM, setarTest, TVAR_LRtest, TAR_simul, TVAR_simul, TVECM_SeoTest)<br> S3method(extend, list)<br> S3method(isLinear, lstar)<br> S3method(toLatex, setar)<p>Modified: trunk/tsDyn/R/SeoTest_grid.R<br>==============================================================================<br>--- trunk/tsDyn/R/SeoTest_grid.R	(original)<br>+++ trunk/tsDyn/R/SeoTest_grid.R	Tue Feb 19 06:36:13 2008<br>@@ -1,4 +1,4 @@<br>-SeoTest&lt;-function(data,lag, beta, trim=0.1,nboot) {<br>+TVECM_SeoTest&lt;-function(data,lag, beta, trim=0.1,nboot, plot=FALSE) {<br> y&lt;-as.matrix(data)<br> T&lt;-nrow(y)<br> k&lt;-ncol(y)<br>@@ -17,23 +17,28 @@<br> 	coint&lt;-lm(y[,1]~ -1 +y[,-1])<br> 	beta&lt;-c(1,-coint$coef)<br> 	print(coint)}	 		#OLS estimation of beta<br>-else 	{beta&lt;-c(1,-beta)}			#Pre-specified beta<br>+else 	{betas&lt;-c(1,-beta)}			#Pre-specified beta<p>-ECTfull&lt;-y%*%beta<br>+ECTfull&lt;-y%*%betas<br> ECT&lt;-ECTfull[-c(1:p,T)]				#ECT<br> ECT2&lt;-embed(ECT,p)<br> Z&lt;-rbind(t(ECT),DeltaX)<p>+#########<br> ###Grid<br>+#########<br> allgammas&lt;-sort(unique(ECT))<br> ng&lt;-length(allgammas)<br>-gammas&lt;-allgammas[(trim*ng):((1-trim)*ng)]<br>-ninter&lt;-round(trim*ng) 			#minimal number of observations in the inter regime<br>+ninter&lt;-round(trim*ng)		#minimal number of obs in each regime<br>+inf&lt;-ceiling(trim*ng+1)<br>+sup&lt;-floor((1-trim)*ng-1)<br>+gammas&lt;-allgammas[inf:sup]<br>+<br> store&lt;-matrix(0, nrow=ng,ncol=ng)<br> store2&lt;-matrix(NA, nrow=ng,ncol=ng)<p>  ###Function which gives Wald test and detSigma from model with two <br>different thresholds	<br>-loop&lt;-function(gam1,gam2){<br>+loop&lt;-function(gam1,gam2, ECT, DeltaX,Y,M){<br> 	##Threshold dummies<br> 	ECTminus &lt;-ifelse(ECT&lt;gam1,1,0)*ECT			<br> 	ECTplus &lt;-ifelse(ECT&gt;gam2, 1,0)*ECT<br>@@ -52,25 +57,40 @@<br> 	list(Wald=Wald, detSigma=detSigma)<br> }#end  loop<p>+loop2&lt;-function(gam1,gam2, ECT, DeltaX,Y,M){<br>+	##Threshold dummies<br>+	ECTminus &lt;-ifelse(ECT&lt;gam1,1,0)*ECT			<br>+	ECTplus &lt;-ifelse(ECT&gt;gam2, 1,0)*ECT<br>+	ThreshECT&lt;-cbind(ECTplus,ECTminus)<br>+<br>+	##Total and partial parameter matrix from TVECM<br>+	Z2&lt;-rbind(t(ThreshECT),DeltaX)<br>+	<br>alpha2&lt;-t(solve(crossprod(ThreshECT,M)%*%ThreshECT)%*%crossprod(ThreshECT,M)%*%t(DeltaY)) <br>#Parameter of TECM<br>+	res&lt;-Y-tcrossprod(Y,Z2)%*%chol2inv(chol(tcrossprod(Z2)))%*%Z2 #All parameters<br>+	###Wald Test<br>+	t(matrix(alpha2, ncol=1))%*% <br>chol2inv(chol(solve(crossprod(ThreshECT,M)%*%ThreshECT)%x%(1/T)*tcrossprod(res,res)))%*%matrix(alpha2, ncol=1)<br>+<br>+}#end  loop<br>+<br> ###Loop for values of the grid<br> for(i in 1:length(gammas)){<br> 	gam1&lt;-gammas[i]<br> 	for (j in 1:length(gammas)){<br> 		if(j&gt;i+ninter){		<br> 			gam2&lt;-gammas[j]<br>-			res&lt;-loop(gam1,gam2)<br>+			res&lt;-loop(gam1=gam1,gam2=gam2,ECT=ECT, DeltaX=DeltaX,Y=Y,M=M)<br> 			store[i,j]&lt;-res$Wald<br> 			store2[i,j]&lt;-res$detSigma<br> 		} #End if<br> 	}	#End for j<br>+<br> }		#end for i<br>-min(store2, na.rm=TRUE)<br>+<p> #################<br> ###Sup Wald model<br> #################<br> supWald&lt;-max(store,na.rm=TRUE)<br>-cat(&quot;SupWald&quot;, supWald, &quot;
&quot;)<p> position&lt;-which(store==max(store, na.rm=TRUE), arr.ind=TRUE)<br> row&lt;-position[1]<br>@@ -79,7 +99,7 @@<br> gamma1&lt;-gammas[row]<br> gamma2&lt;-gammas[col]<p>-resultw&lt;-loop(gamma1,gamma2)<br>+resultw&lt;-loop(gamma1,gamma2,ECT=ECT, DeltaX=DeltaX,Y=Y,M=M)<br> cat(&quot;SupWald Model 
