&quot;)<p>@@ -118,17 +138,18 @@<br> Xminus1[1:(lag+1),]&lt;-y[(1):(lag+1),]<br> ECTtminus1&lt;-matrix(0,nrow=nrow(y), ncol=1)		#ECT term<p>-resSig&lt;-rbind(matrix(0,nrow=lag, ncol=k),resSig)	<br>+<p><br> ###Boostrap the residuals<br>-bootstraploop&lt;-function(beta){<br>+bootstraploop&lt;-function(vec_beta){<p>-resSig&lt;-apply(resSig,2,sample, replace=TRUE) 		#comment this line to <br>check the adequacy<br>+resb&lt;-rbind(0,apply(resSig,2,sample, replace=TRUE))<br>+#resb&lt;-rbind(matrix(0,nrow=lag, ncol=k),resSig)		#uncomment this line <br>to check the adequacy<br> for(i in (lag+2):(nrow(y)-1)){<br> 	Xminus1[i,]&lt;-Xminus1[i-1,]+Yb[i-1,]<br>-	ECTtminus1[i]&lt;-Xminus1[i,]%*%beta<br>-	Yb[i,]&lt;-apply(cbind(Bsig[,3], <br>Bsig[,-c(1:3)]%*%matrix(t(Yb[i-c(1:lag),]), ncol=1),resSig[i,]),1,sum)<br>+	ECTtminus1[i]&lt;-Xminus1[i,]%*%vec_beta<br>+	Yb[i,]&lt;-apply(cbind(Bsig[,3], <br>Bsig[,-c(1:3)]%*%matrix(t(Yb[i-c(1:lag),]), ncol=1),resb[i,]),1,sum)<br> 	if(ECTtminus1[i]&lt;gamma1Sigma) {Yb[i,]&lt;-apply(cbind(Bsig[,1]*ECTtminus1[i,],Yb[i,]),1,sum)}<br> 	if(ECTtminus1[i]&gt;gamma2Sigma) {Yb[i,]&lt;-apply(cbind(Bsig[,2]*ECTtminus1[i,],Yb[i,]),1,sum)}<br> }<br>@@ -136,34 +157,41 @@<br>  yboot&lt;-apply(rbind(y[1,],Yb),2,cumsum)			#same as diffinv but it did <br>not work<p> ### Regression on the new series<br>+<br>+ECTboot&lt;-(y%*%c(1,-beta))[-c(1:p,T)]<br> DeltaYboot&lt;-t(diff(yboot))[,(p+1):(T-1)] 		<br>-DeltaXboot&lt;-rbind(rep(1,ncol(DeltaYboot)),t(embed(diff(yboot),p+1)[,-(1:k)]))<br>+DeltaXboot&lt;-rbind(1,t(embed(diff(yboot),p+1)[,-(1:k)]))<br> Mboot&lt;-diag(1,T-p-1)-t(DeltaXboot)%*%chol2inv(chol(tcrossprod(DeltaXboot)))%*%DeltaXboot<p>-ECTminusboot &lt;-ifelse(ECT&lt;gamma1, 1,0)*ECT	<br>-ECTplusboot &lt;-ifelse(ECT&gt;gamma2, 1,0)*ECT<br>-ThreshECTboot&lt;-cbind(ECTminusboot,ECTplusboot)<br>-Zboot&lt;-rbind(t(ThreshECTboot),DeltaX)<br>-<br>-Bboot&lt;-tcrossprod(DeltaYboot,Zboot)%*%chol2inv(chol(tcrossprod(Zboot)))	 <br>	#All parameters<br>-<br>-alpha2boot&lt;-t(solve(crossprod(ThreshECTboot,M)%*%ThreshECTboot)%*%crossprod(ThreshECTboot,M)%*%t(DeltaYboot)) <br>#coin slope para<br>-resboot&lt;-DeltaYboot-Bboot%*%Zboot					#residuals	<br>-Sigmaboot&lt;-(1/T)*resboot%*%t(resboot)					#Sigma from model<br>+gammasb&lt;-sort(unique(ECTboot))[inf:sup]<br>+storeb&lt;-matrix(0, nrow=ng,ncol=ng)<br>+<br>+###Loop for values of the grid<br>+for(i in 1:length(gammasb)){<br>+	gam1&lt;-gammasb[i]<br>+	for (j in 1:length(gammasb)){<br>+		if(j&gt;i+ninter){		<br>+			gam2&lt;-gammasb[j]<br>+			res&lt;-loop(gam1,gam2,ECT=ECTboot, DeltaX=DeltaXboot,Y=DeltaYboot,M=Mboot)<br>+			storeb[i,j]&lt;-res$Wald<br>+		} #End if<br>+	}	#End for j<br>+}		#end for i<p>-Waldboot&lt;-t(matrix(alpha2boot,ncol=1)) %*%solve(solve(t(ThreshECTboot) %*%Mboot%*%ThreshECTboot)%x%Sigmaboot)%*%matrix(alpha2boot, <br>ncol=1)<br>-Waldboot<br>+supWaldboot&lt;-max(storeb)<br>+return(supWaldboot)<br> }#end of the bootstrap loop<p>-Waldboots&lt;-replicate(nboot,bootstraploop(beta))<br>-PvalBoot&lt;-sum(ifelse(Waldboots&gt;supWald,1,0))/nboot<br>+Waldboots&lt;-replicate(nboot,bootstraploop(c(1,-beta)))<br>+PvalBoot&lt;-mean(ifelse(Waldboots&gt;supWald,1,0))<br> CriticalValBoot&lt;-quantile(Waldboots, probs=c(0.9, 0.95, 0.975,0.99))<p> ###Graphical output<br>-plot(density(Waldboots))<br>-abline(v=c(supWald, CriticalValBoot[c(1,2)]), lty=c(1,2,3), col=c(2,3,4))<br>-legend(&quot;topright&quot;, legend=c(&quot;SupWald&quot;, &quot;Boot 10%&quot;, &quot;Boot 5%&quot;), <br>col=c(2,3,4), lty=c(1,2,3))<br>-<br>+if(plot==TRUE){<br>+	plot(density(Waldboots))<br>+	abline(v=c(supWald, CriticalValBoot[c(1,2)]), lty=c(1,2,3), col=c(2,3,4))<br>+	legend(&quot;topright&quot;, legend=c(&quot;SupWald&quot;, &quot;Boot 10%&quot;, &quot;Boot 5%&quot;), <br>col=c(2,3,4), lty=c(1,2,3))<br>+}<p><br> ###Output<br>@@ -173,8 +201,10 @@<br> }<p> if(FALSE) {#usage example<br>+<br> data(zeroyld)<br> data&lt;-zeroyld<p>-SeoTest(data[1:100,],lag=2, beta=1, trim=0.15, nboot=200)<br>+<br>+TVECM_SeoTest(data[1:100,],lag=1, beta=1.1, trim=0.15, nboot=1, plot=FALSE)<br> }<p>Modified: trunk/tsDyn/R/TAR_simul.R<br>==============================================================================<br>--- trunk/tsDyn/R/TAR_simul.R	(original)<br>+++ trunk/tsDyn/R/TAR_simul.R	Tue Feb 19 06:36:13 2008<br>@@ -51,10 +51,10 @@<br>         z &lt;- xx %*% mTh<br>         dim(z) &lt;- NULL<br>     }<br>-    else if (!missing(thVar)) {<br>+    else if (!missing(thVar)) { stop(&quot;thVar argument currenly not implemented&quot;)<br>         if (length(thVar) &gt; nrow(x)) {thVar &lt;- thVar[seq_len(nrow(x))]}<br>  	if (length(thVar) &lt; nrow(x)) {stop(&quot;The threshold variable should not <br>be smaller than the serie&quot;) }<br>-	z&lt;-nlar.struct(x = thVar, m = m, d = d, steps = steps, series = <br>deparse(substitute(z)))[, thDelay + 1]<br>+	z&lt;-nlar.struct(x = thVar, m = m, d = 1, steps = 1, series = <br>deparse(substitute(z)))[, thDelay + 1]<br>     }<br>     else {z &lt;- xx[, thDelay]<br>     }<br>@@ -99,10 +99,9 @@<br> ###Bootstrap for the F test<br> ##############################<br> #initial values<br>-Yb&lt;-vector(&quot;numeric&quot;, length=length(x))		#Delta Y term<br>+Yb&lt;-vector(&quot;numeric&quot;, length=length(y))		#Delta Y term<br> Yb[1:p]&lt;-y[1:p]<p>-if(!missing(thVar))  <br>zext&lt;-embed(thVar,m+1)[round(trim*ng):round((1-trim)*ng),]		<p> z2&lt;-vector(&quot;numeric&quot;, length=length(y))<br> z2[1:p]&lt;-y[1:p]<p>Added: trunk/tsDyn/R/TVAR_LRtest.R<br>==============================================================================<br>--- (empty file)<br>+++ trunk/tsDyn/R/TVAR_LRtest.R	Tue Feb 19 06:36:13 2008<br>@@ -0,0 +1,392 @@<br>+TVAR_LRtest &lt;- function (data, m=1, d = 1, steps = d, trend=TRUE, <br>series, thDelay = 1:2, mTh=1, thVar, nboot=10, plot=FALSE, trim=0.1, <br>test=c(&quot;1vs&quot;, &quot;2vs3&quot;)) {<br>+    if (missing(series))  series &lt;- deparse(substitute(x))<br>+y &lt;- as.matrix(data)<br>+Torigin &lt;- nrow(y) 	#Size of original sample<br>+#if(type==&quot;difference&quot;) {y&lt;-diff(y)}<br>+T &lt;- nrow(y) 		#Size of start sample<br>+t &lt;- T-m 		#Size of end sample<br>+k &lt;- ncol(y) 		#Number of variables<br>+p&lt;-m<br>+if(is.null(colnames(data)))<br>+	colnames(data)&lt;-paste(&quot;Var&quot;, seq_len(k), sep=&quot;&quot;)<br>+if(max(thDelay)&gt;m)<br>+	stop(&quot;Max of thDelay should be smaller or equal to the number of lags&quot;)<br>+ndig&lt;-getndp(y)<br>+Y &lt;- y[(m+1):T,] #<br>+Z &lt;- embed(y, m+1)[, -seq_len(k)]	#Lags matrix<br>+a&lt;-0<br>+if(trend==TRUE){<br>+	Z &lt;- cbind(1,Z)<br>+	a&lt;-1}<br>+else<br>+	warning(&quot;The test was currently implemented for a model with trend. <br>Results could be altered without trend&quot;)<br>+npar &lt;- ncol(Z)		<br>+<br>+cat(&quot;Warning: the thDelay values do not correspond to the univariate <br>implementation in tsdyn
&quot;)<br>+<br>+##################<br>+###Linear model<br>+#################<br>+B&lt;-t(Y)%*%Z%*%solve(t(Z)%*%Z)		#B: OLS parameters, dim 2 x npar<br>+res&lt;-Y-Z%*%t(B)<br>+Sigma&lt;- matrix(1/T*crossprod(res),ncol=k)<br>+<br>+<br>+Y&lt;-t(Y)<br>+########################<br>+### Threshold variable<br>+########################<br>+<br>+###External threshold variable<br>+if (!missing(thVar)) {		<br>+        if (length(thVar) &gt; Torigin) {<br>+		z &lt;- thVar[seq_len(Torigin)]<br>+		warning(&quot;The external threshold variable is not of same length as <br>the original variable&quot;)<br>+        }<br>+        else<br>+		z &lt;- thVar<br>+	z&lt;-embed(z,p+1)[,seq_len(max(thDelay))+1]		#if thDelay=2, ncol(z)=2<br>+}<br>+<br>+###Combination (or single value indicating position) of <br>contemporaneous variables<br>+<br>+else {<br>+	if (length(mTh) &gt; k)<br>+		stop(&quot;length of &#39;mTh&#39; should be equal to the number of variables, or <br>just one&quot;)<br>+	if(length(mTh)==1) {<br>+		if(mTh&gt;p)<br>+			stop(&quot;mTh too big, should be smaller or equal to the number of variables&quot;)<br>+		combin &lt;- matrix(0,ncol=1, nrow=k)<br>+		combin[mTh,]&lt;-1<br>+	}<br>+	else<br>+		combin&lt;-matrix(mTh,ncol=1, nrow=k)<br>+	zcombin &lt;- y %*% combin<br>+	z &lt;- embed(zcombin,p+1)[,seq_len(max(thDelay))+1]		#if thDelay=2, ncol(z)=2<br>+}<br>+<br>+<br>+<br>+<br>+###############################<br>+###Grid for transition variable<br>+###############################<br>+<br>+if(length(thDelay)==1)<br>+	b&lt;-1<br>+else b&lt;-thDelay<br>+	<br>+allgammas&lt;-sort(unique(z[,b]))<br>+ng&lt;-length(allgammas)<br>+ninter&lt;-round(trim*ng)<br>+gammas&lt;-allgammas[ceiling(trim*ng+1):floor((1-trim)*ng-1)]<br>+<br>+<br>+###################<br>+###Search function<br>+##################<br>+<br>+SSR_1thresh&lt;- function(grid,Z,Y, trans){<br>+	d&lt;-grid[1]<br>+	gam1&lt;-grid[2]<br>+	##Threshold dummies<br>+	d1&lt;-ifelse(trans[,d]&lt;gam1, 1,0)<br>+	regimeDown &lt;- d1 * Z<br>+	regimeUp&lt;-(1-d1)*Z<br>+	##SSR<br>+	Z1 &lt;- t(cbind(regimeDown, regimeUp))		# dim k(p+1) x t<br>+	crossprod(c(Y - tcrossprod(Y,Z1) %*% solve(tcrossprod(Z1))%*% Z1))<br>+} #end of the function<br>+<br>+Sigma_1thresh&lt;- function(gam1, d,Z,Y, trans){<br>+	##Threshold dummies<br>+	d1&lt;-ifelse(trans[,d]&lt;gam1, 1,0)<br>+	regimeDown &lt;- d1 * Z<br>+	regimeUp&lt;-(1-d1)*Z<br>+	##SSR<br>+	Z1 &lt;- t(cbind(regimeDown, regimeUp))		# dim k(p+1) x t<br>+	B1 &lt;- tcrossprod(Y,Z1) %*% solve(tcrossprod(Z1))<br>+	matrix(1/T*tcrossprod(Y - B1 %*% Z1),ncol=k)<br>+} #end of the function<br>+<br>+SSR_2thresh &lt;- function(gam1,gam2,d,Z,Y,trans){<br>+	##Threshold dummies<br>+	dummydown &lt;- ifelse(trans[,d]&lt;gam1, 1, 0)<br>+	regimedown &lt;- dummydown*Z<br>+	ndown &lt;- mean(dummydown)<br>+	dummyup &lt;- ifelse(trans[,d]&gt;=gam2, 1, 0)<br>+	regimeup &lt;- dummyup*Z<br>+	nup &lt;- mean(dummyup)<br>+	##SSR from TVAR(3)<br>+	#print(c(ndown,1-nup-ndown,nup))<br>+	if(min(nup, ndown, 1-nup-ndown)&gt;trim){<br>+		Z2 &lt;- t(cbind(regimedown, (1-dummydown-dummyup)*Z, regimeup))		# dim <br>k(p+1) x t	<br>+		resid &lt;- crossprod(c( Y - tcrossprod(Y,Z2) %*%  <br>solve(tcrossprod(Z2))%*%Z2))	#SSR<br>+	}<br>+	else<br>+		resid &lt;- NA<br>+	return(resid)<br>+}<br>+<br>+Sigma_2thresh &lt;- function(gam1,gam2,d,Z,Y,trans){<br>+	##Threshold dummies<br>+	dummydown &lt;- ifelse(trans[,d]&lt;gam1, 1, 0)<br>+	regimedown &lt;- dummydown*Z<br>+	dummyup &lt;- ifelse(trans[,d]&gt;=gam2, 1, 0)<br>+	regimeup &lt;- dummyup*Z<br>+	##SSR from TVAR(3)<br>+	#print(c(ndown,1-nup-ndown,nup))<br>+	Z2 &lt;- t(cbind(regimedown, (1-dummydown-dummyup)*Z, regimeup))		# dim <br>k(p+1) x t	<br>+	matrix(1/T*tcrossprod(Y - tcrossprod(Y,Z2) %*% solve(tcrossprod(Z2))%*%Z2),ncol=k)<br>+}<br>+<br>+##################<br>+###One threshold<br>+##################<br>+<br>+IDS&lt;-as.matrix(expand.grid(thDelay, gammas))<br>+result &lt;- apply(IDS, 1, SSR_1thresh,Z=Z, Y=Y,trans=z)<br>+bestDelay&lt;-IDS[which.min(result),1]<br>+bestThresh&lt;-IDS[which.min(result),2]<br>+cat(&quot;Best unique threshold&quot;, bestThresh, &quot;				 SSR&quot;, min(result), &quot;
